/**
 * Single-file report bundler.
 *
 * Produces ONE self-contained .html containing both the dashboard and the
 * full findings list, with every screenshot embedded as a data: URI. No
 * sibling files, no shots/ folder, no server, no hosting — download the one
 * file, double-click it, and the whole report is there.
 *
 * Why this exists: the normal output is a folder (dashboard + report +
 * shots/). Azure DevOps serves pipeline artifacts as downloads, so getting to
 * the report meant fetching an archive and unpacking it; and a single file
 * pulled out of that archive rendered without its evidence images, because
 * the <img> paths are relative. A single file with the images inlined is
 * downloadable in one click and correct on its own.
 *
 * Merge notes (both documents are generated by lib/report.js, so this is
 * merging two known quantities, not arbitrary HTML):
 *   · Both views share one masthead (fenced by <!--ac:mast--> markers); the
 *     bundle keeps the dashboard's copy and turns its view links into tabs.
 *   · The findings view's ids are all prefixed `fx-` and its script only looks
 *     inside #fx-main, so it is kept as-is next to the dashboard's script.
 *   · The controller here only switches views and forwards deep links to the
 *     findings view (window.__acFindingsScope).
 */
const fs = require('fs');
const path = require('path');

const MIME = { '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.gif': 'image/gif', '.webp': 'image/webp' };

// Every <style> block in the document head, in order (a view can carry more than one).
const stylesOf = (html) => {
  const head = (html.match(/<head>([\s\S]*?)<\/head>/) || [, html])[1];
  return [...head.matchAll(/<style>([\s\S]*?)<\/style>/g)].map((m) => m[1]);
};
const bodyOf = (html) => {
  const m = html.match(/<body>([\s\S]*)<\/body>/);
  return m ? m[1] : html;
};
// The shared masthead (lib/report.js) is fenced by markers so one copy can be kept.
const MAST = /<!--ac:mast-->([\s\S]*?)<!--\/ac:mast-->/;
const titleOf = (html) => {
  const m = html.match(/<title>([\s\S]*?)<\/title>/);
  return m ? m[1] : 'Accessibility Report';
};

/**
 * Replace every relative <img src="..."> with a data: URI.
 * Looks for each referenced file across the supplied roots, first match wins.
 * Missing files are left untouched rather than blanked, so a broken path stays
 * visible as a broken image instead of silently disappearing.
 */
function inlineImages(html, roots, log = () => {}) {
  const cache = new Map();
  let embedded = 0, missing = 0, bytes = 0;

  const out = html.replace(/(<img\b[^>]*?\bsrc=")([^"]+)(")/g, (full, pre, src, post) => {
    if (/^(data:|https?:|\/\/)/i.test(src)) return full;
    if (cache.has(src)) { embedded++; return pre + cache.get(src) + post; }

    for (const root of roots) {
      const file = path.join(root, src);
      if (!fs.existsSync(file)) continue;
      try {
        const buf = fs.readFileSync(file);
        const uri = `data:${MIME[path.extname(file).toLowerCase()] || 'application/octet-stream'};base64,${buf.toString('base64')}`;
        cache.set(src, uri);
        embedded++; bytes += buf.length;
        return pre + uri + post;
      } catch (e) { /* fall through to the next root */ }
    }
    missing++;
    return full;
  });

  log(`   • inlined ${cache.size} unique image(s) across ${embedded} reference(s)`
    + `${missing ? `, ${missing} not found` : ''} (${(bytes / 1e6).toFixed(1)} MB before encoding)`);
  return out;
}

/** Switches between the views. Filtering inside each view is the view's own script. */
const CONTROLLER = `<script>
(function(){
  var views = { summary: document.getElementById('view-summary'),
                plan: document.getElementById('view-plan'),
                findings: document.getElementById('view-findings') };
  var mains = { summary: 'main', plan: 'pl-main', findings: 'fx-main' };
  var skip = document.querySelector('.ac-skip');

  function show(name, keepScroll){
    if (!views[name]) name = 'summary';
    Object.keys(views).forEach(function(k){ if (views[k]) views[k].hidden = (k !== name); });
    [].forEach.call(document.querySelectorAll('.ac-views a[data-view]'), function(t){
      if (t.dataset.view === name) t.setAttribute('aria-current', 'page'); else t.removeAttribute('aria-current');
    });
    if (skip) skip.setAttribute('href', '#' + mains[name]);
    if (history.replaceState) history.replaceState(null, '', '#' + name);
    if (!keepScroll) window.scrollTo(0, 0);
    if (window.__acToc) window.__acToc();
  }

  document.addEventListener('click', function(e){
    var a = e.target.closest && e.target.closest('a[data-view], a[data-deeplink]');
    if (!a) return;
    e.preventDefault();
    if (a.hasAttribute('data-deeplink')) {
      if (window.__acFindingsScope) window.__acFindingsScope(a.dataset.page || '', a.dataset.state || '', null);
      show('findings');
    } else {
      show(a.dataset.view);
    }
  });

  var start = (location.hash || '').slice(1);
  show(views[start] ? start : 'summary', true);
})();
</script>`;

const TAB_CSS = `
.ac-planwrap{display:block;min-width:0}
.ac-planwrap .fp{max-width:1280px;padding-left:1.5rem;padding-right:1.5rem}
.ac-planwrap .fp-head h2{font-size:1.35rem;margin:0 0 4px;color:var(--ink)}
/* The masthead already has Commands. */
.ac-planwrap #fp-cmds-btn{display:none}
@media (max-width:700px){.ac-planwrap .fp{padding-left:1rem;padding-right:1rem}}
@media print{#view-summary[hidden],#view-plan[hidden],#view-findings[hidden]{display:none!important}}
`;

/**
 * @param {string} outDir      where to write the bundle
 * @param {object} html        { dashboard, report, plan? } — generated HTML strings;
 *                             plan is renderFixPlan(..., {mode:'bundle'}) → {body, css}
 * @param {object} opts        { shotRoots: string[], file, log }
 * @returns {{file:string, bytes:number}}
 */
function writeSingleFile(outDir, html, opts = {}) {
  const log = opts.log || (() => {});
  const file = path.join(outDir, opts.file || 'accessibility-report.html');
  const planTab = html.plan && html.plan.body;

  let dash = bodyOf(html.dashboard);
  let rep = bodyOf(html.report);

  // One masthead for every view: keep the dashboard's, drop the findings copy.
  const mastMatch = dash.match(MAST);
  let mast = mastMatch ? mastMatch[1] : '';
  dash = dash.replace(MAST, '');
  rep = rep.replace(MAST, '');
  mast = mast.replace(/(<p class="ac-sub">[\s\S]*?)(<\/p>)/, '$1 · single file, works offline$2');

  // Links between the files become view switches.
  //   …report.html?page=X&state=Y  ->  data-deeplink (scopes the findings view)
  const escAttr = (s) => String(s || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
  const relink = (s) => s
    .replace(/<a href="[^"]*report\.html\?([^"]*)"/g, (full, qs) => {
      const p = new URLSearchParams(qs.replace(/&amp;/g, '&'));
      return `<a href="#findings" data-deeplink data-page="${escAttr(p.get('page'))}" data-state="${escAttr(p.get('state'))}"`;
    })
    .replace(/<a href="[^"]*" data-view="(summary|plan|findings)"/g, (full, v) => `<a href="#${v}" data-view="${v}"`);
  mast = relink(mast);
  dash = relink(dash);
  rep = relink(rep);
  // Without a fix plan there is no tab to switch to: drop links that point at it.
  if (!planTab) {
    mast = mast.replace(/<a href="#plan" data-view="plan"[^>]*>[\s\S]*?<\/a>/g, '');
    dash = dash.replace(/<a [^>]*href="#plan" data-view="plan"[^>]*>[\s\S]*?<\/a>/g, '');
  }

  // Screenshots -> data: URIs. Only the findings view carries images.
  const roots = opts.shotRoots || [outDir];
  rep = inlineImages(rep, roots, log);

  const seen = new Set();
  const css = [...stylesOf(html.dashboard), ...stylesOf(html.report)].filter((c) => (seen.has(c) ? false : seen.add(c))).join('\n');
  const title = (html.dashboard.match(/<title>([\s\S]*?)<\/title>/) || [, 'Accessibility report'])[1].replace(/ · Overview$/, '');

  const doc = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${title}</title>
<style>${css}${TAB_CSS}${planTab ? html.plan.css : ''}</style></head><body>
${mast}
<div id="view-summary">${dash}</div>
${planTab ? `<div id="view-plan" hidden><main class="ac-planwrap" id="pl-main" tabindex="-1">${html.plan.body}</main></div>` : ''}
<div id="view-findings" hidden>${rep}</div>
${CONTROLLER}
</body></html>`;

  fs.writeFileSync(file, doc);
  const bytes = Buffer.byteLength(doc);
  log(`   • single-file report: ${(bytes / 1e6).toFixed(1)} MB → ${path.basename(file)}`);
  return { file, bytes };
}

module.exports = { writeSingleFile, inlineImages };
